/**
 * Owns Scholar/Mentor state normalization, detached choice data and finite resolution.
 * Inputs are original data structures, roster and choices; outputs preserve writable copied
 * states and literal effect summaries. This boundary never stores a World or grants a lease;
 * the night-frame owner validates live references and commits actual resources.
 */
import type {
  ModifierCaster,
  ModifierMode,
  ModifierChoice,
  ModifierState,
  ModifierPlayer,
  CommittedModifier,
  ModifierResolution,
  ModifierReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";

export const SCHOLAR_MENTOR_POLICY = "awa_scholar_mentor_twelve_v1" as const;
function object(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !types.isProxy(value) && !Array.isArray(value);
}
function keys(value: Record<string, unknown>, allowed: string[]): boolean {
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === allowed.length &&
    allowed.every((key) => descriptors[key] !== undefined && "value" in descriptors[key]!)
  );
}
function arrayItems(value: unknown): unknown[] | undefined {
  if (!Array.isArray(value) || types.isProxy(value)) return undefined;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  const length: unknown = Object.getOwnPropertyDescriptor(value, "length")?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(descriptors).length !== length + 1
  )
    return undefined;
  const out: unknown[] = [];
  for (let index = 0; index < length; index++) {
    const descriptor = descriptors[String(index)];
    if (!descriptor || !("value" in descriptor)) return undefined;
    out.push(descriptor.value);
  }
  return out;
}
export function createModifierState(caster: ModifierCaster): ModifierState {
  if (caster !== "day_scholar" && caster !== "night_mentor")
    throw new Error("modifier_caster_invalid");
  return {
    policy: SCHOLAR_MENTOR_POLICY,
    caster,
    remaining: { enhance: 1, weaken: 1 },
    history: [],
  };
}
export function readModifierState(value: unknown): ModifierState | undefined {
  if (
    !object(value) ||
    !keys(value, ["policy", "caster", "remaining", "history"]) ||
    value.policy !== SCHOLAR_MENTOR_POLICY ||
    (value.caster !== "day_scholar" && value.caster !== "night_mentor") ||
    !object(value.remaining) ||
    !keys(value.remaining, ["enhance", "weaken"]) ||
    !Array.isArray(value.history)
  )
    return undefined;
  const items = arrayItems(value.history);
  if (!items) return undefined;
  let last = 1,
    enhance = 1,
    weaken = 1;
  const history: ModifierChoice[] = [];
  for (const item of items) {
    if (
      !object(item) ||
      !keys(item, ["day", "mode", "targetId"]) ||
      typeof item.day !== "number" ||
      !Number.isSafeInteger(item.day) ||
      item.day >= Number.MAX_SAFE_INTEGER ||
      item.day <= last ||
      (item.mode !== null && item.mode !== "enhance" && item.mode !== "weaken")
    )
      return undefined;
    if (
      item.mode === null
        ? item.targetId !== null
        : typeof item.targetId !== "number" ||
          !Number.isSafeInteger(item.targetId) ||
          item.targetId < 1
    )
      return undefined;
    if (item.mode === "enhance") enhance--;
    if (item.mode === "weaken") weaken--;
    if (enhance < 0 || weaken < 0) return undefined;
    last = item.day;
    history.push({ day: item.day, mode: item.mode, targetId: item.targetId as number | null });
  }
  if (value.remaining.enhance !== enhance || value.remaining.weaken !== weaken) return undefined;
  return {
    policy: SCHOLAR_MENTOR_POLICY,
    caster: value.caster,
    remaining: { enhance, weaken },
    history,
  };
}
/** Pure selection: no effect or collision is revealed to the caster. */
export function selectModifier(
  state: ModifierReadState,
  day: number,
  mode: ModifierMode | null,
  targetId: number | null,
  livingIds: readonly number[],
): ModifierState {
  const next = readModifierState(state);
  if (
    !next ||
    !Number.isSafeInteger(day) ||
    day >= Number.MAX_SAFE_INTEGER ||
    day < 2 ||
    day <= (next.history.at(-1)?.day ?? 1)
  )
    throw new Error("modifier_choice_day_invalid");
  if (mode !== null && mode !== "enhance" && mode !== "weaken")
    throw new Error("modifier_mode_invalid");
  if (
    mode === null
      ? targetId !== null
      : targetId === null ||
        !Number.isSafeInteger(targetId) ||
        targetId < 1 ||
        !livingIds.includes(targetId)
  )
    throw new Error("modifier_target_invalid");
  if (mode !== null) {
    if (next.remaining[mode] !== 1) throw new Error("modifier_charge_spent");
    next.remaining[mode] = 0;
  }
  next.history.push({ day, mode, targetId });
  return next;
}
/** Finite-board resolution. Immune caster targets are filtered before collision. */
export function resolveModifiers(
  players: readonly ModifierPlayer[],
  selections: readonly CommittedModifier[],
): ModifierResolution {
  const roster = new Map(players.map((player) => [player.id, player]));
  if (
    roster.size !== players.length ||
    players.some((p) => !Number.isSafeInteger(p.id) || p.id < 1)
  )
    throw new Error("modifier_roster_invalid");
  const deck: Record<string, { count: number; camp: "good" | "wolf" }> = {
    wolf: { count: 3, camp: "wolf" },
    night_mentor: { count: 1, camp: "wolf" },
    villager: { count: 4, camp: "good" },
    day_scholar: { count: 1, camp: "good" },
    seer: { count: 1, camp: "good" },
    guard: { count: 1, camp: "good" },
    witch: { count: 1, camp: "good" },
  };
  if (
    players.length !== 12 ||
    players.some((p) => !Object.hasOwn(deck, p.role) || deck[p.role]!.camp !== p.camp) ||
    Object.entries(deck).some(
      ([role, spec]) => players.filter((p) => p.role === role).length !== spec.count,
    )
  )
    throw new Error("modifier_roster_invalid");
  const actors = new Set<number>(),
    casters = new Set<ModifierCaster>();
  const effective: CommittedModifier[] = [];
  for (const selection of selections) {
    const actor = roster.get(selection.actorId),
      target = roster.get(selection.targetId);
    if (
      !actor?.alive ||
      !target?.alive ||
      actor.role !== selection.caster ||
      (selection.caster !== "day_scholar" && selection.caster !== "night_mentor") ||
      actor.camp !== (selection.caster === "day_scholar" ? "good" : "wolf") ||
      (selection.mode !== "enhance" && selection.mode !== "weaken") ||
      actors.has(actor.id) ||
      casters.has(selection.caster)
    )
      throw new Error("modifier_selection_invalid");
    actors.add(actor.id);
    casters.add(selection.caster);
    if (target.role !== "day_scholar" && target.role !== "night_mentor")
      effective.push({ ...selection });
  }
  const out: ModifierResolution = {
    pendingDeaths: [],
    conflict: null,
    goodEffects: [],
    bonusKnifeActorId: null,
    blockWolfKnife: false,
  };
  if (effective.length === 2) {
    const [a, b] = effective as [CommittedModifier, CommittedModifier];
    const first = roster.get(a.targetId)!,
      second = roster.get(b.targetId)!;
    if (first.camp === "good" && first.id === second.id) {
      out.pendingDeaths = [first.id];
      out.conflict = "same_good";
      return out;
    }
    if (first.camp === "wolf" && second.camp === "wolf") {
      out.pendingDeaths = [effective.find((s) => s.caster === "night_mentor")!.actorId];
      out.conflict = "both_wolves";
      return out;
    }
  }
  for (const selection of effective) {
    const target = roster.get(selection.targetId)!;
    if (target.camp === "wolf") {
      if (selection.mode === "weaken") out.blockWolfKnife = true;
      else out.bonusKnifeActorId = target.id;
    } else if (target.role === "seer" || target.role === "guard" || target.role === "witch") {
      out.goodEffects.push({ targetId: target.id, role: target.role, mode: selection.mode });
    }
  }
  return out;
}

/**
 * 负责 白昼学者／寂夜导师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { SCHOLAR_MENTOR_POLICY, createModifierState } from "./state";
import {
  scholarMentorStateForRole,
  scholarMentorChoicePending,
  scholarMentorChoiceTargets,
  scholarMentorRoleCanKnife,
  scholarMentorBonusTargets,
  captureScholarMentorBonus,
  isScholarMentorBoard,
} from "./night_frame";
import { SCHOLAR_MENTOR_NIGHT_STAGES } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(SCHOLAR_MENTOR_POLICY).default(SCHOLAR_MENTOR_POLICY),
});
const supported = [
  Role.Wolf,
  Role.NightMentor,
  Role.Villager,
  Role.DayScholar,
  Role.Seer,
  Role.Witch,
  Role.Guard,
];
function profile(roleNameId: Role.DayScholar | Role.NightMentor): NativeRoleContributions {
  const mentor = roleNameId === Role.NightMentor;
  const base = mentor ? ORDINARY_WOLF_CONTRIBUTIONS : undefined;
  return {
    metadata: {
      ...base?.metadata,
      role: roleNameId,
      camp: mentor ? Camp.Wolf : Camp.Good,
      goodSide: mentor ? undefined : "god",
      maxCount: 1,
      supportedWinConditions: [WinCondition.SlaughterSide],
      supportedBoardRoles: supported,
      label: roleName(roleNameId),
      skillBrief: text("zh-CN", mentor ? "role.night_mentor.brief" : "role.day_scholar.brief"),
    },
    runtime: {
      ...base?.runtime,
      canSelfDestruct: false,
      wolfTeam: mentor
        ? (role, world) => ({
            recognizedByPack: true,
            recognizes: "none",
            canChat: false,
            canVoteForKill: scholarMentorRoleCanKnife(world, role),
          })
        : undefined,
      init: (role, ctx) => {
        parameters.parse(ctx.boardConfig?.scholarMentor ?? {});
        role.privateState.scholarMentor = createModifierState(
          mentor ? "night_mentor" : "day_scholar",
        );
      },
      configuration: {
        schema: parameters,
        defaults: parameters.parse({}),
        apply: (config, value) => ({ ...config, scholarMentor: parameters.parse(value) }),
        serialize: (config) => parameters.parse(config.scholarMentor ?? {}),
      },
      toolSpecs: [
        ...(base?.runtime.toolSpecs ?? []),
        {
          name: "modify_skill",
          parameters: {
            type: "object",
            properties: {
              mode: { type: ["string", "null"], enum: ["enhance", "weaken", null] },
              target_id: { type: ["integer", "null"], minimum: 1 },
            },
            required: ["mode", "target_id"],
            additionalProperties: false,
          },
          argHint: 'modify_skill args: {"mode":"enhance"|"weaken"|null,"target_id":number|null}',
          userPromptHintKey: "action.modify_skill.hint",
        },
        {
          name: "bonus_action",
          parameters: {
            type: "object",
            properties: {
              kind: { type: "string", enum: ["check", "guard", "poison", "kill"] },
              target_id: { type: ["integer", "null"], minimum: 1 },
              abstain: { type: "boolean" },
            },
            required: ["kind", "target_id", "abstain"],
            additionalProperties: false,
          },
          argHint:
            'bonus_action args: {"kind":"check"|"guard"|"poison"|"kill","target_id":number|null,"abstain":boolean}',
          userPromptHintKey: "action.bonus_action.hint",
        },
      ],
      stageDirectives: [
        ...(base?.runtime.stageDirectives ?? []),
        {
          match: (tools) => tools.length === 1 && tools[0] === "modify_skill",
          messageKey: "action.modify_skill.directive",
          text: text("zh-CN", "action.modify_skill.directive"),
        },
        {
          match: (tools) => tools.length === 1 && tools[0] === "bonus_action",
          messageKey: "action.bonus_action.directive",
          text: text("zh-CN", "action.bonus_action.directive"),
        },
      ],
      validationRules: {
        ...base?.runtime.validationRules,
        modify_skill: ({ world, role, actorId, day, phase, toolCall }) => {
          const state = scholarMentorStateForRole(role);
          if (
            !state ||
            !isScholarMentorBoard(world) ||
            day === undefined ||
            phase !== Phase.Night ||
            toolCall.name !== "modify_skill" ||
            !scholarMentorChoicePending(world, day, actorId)
          )
            return { code: RuleError.ModifierUnavailable };
          const { mode, target_id } = toolCall.args;
          if (mode === null) return target_id === null ? null : { code: RuleError.ModifierTarget };
          return (mode === "enhance" || mode === "weaken") &&
            state.remaining[mode] === 1 &&
            target_id !== null &&
            scholarMentorChoiceTargets(world, day, actorId).includes(target_id)
            ? null
            : { code: RuleError.ModifierTarget };
        },
        bonus_action: ({ world, actorId, day, phase, toolCall }) => {
          if (
            !isScholarMentorBoard(world) ||
            day === undefined ||
            phase !== Phase.Night ||
            toolCall.name !== "bonus_action"
          )
            return { code: RuleError.ModifierUnavailable };
          const { kind, target_id, abstain } = toolCall.args;
          if (
            !["check", "guard", "poison", "kill"].includes(kind) ||
            typeof abstain !== "boolean" ||
            (abstain ? target_id !== null : target_id === null)
          )
            return { code: RuleError.ModifierTarget };
          try {
            captureScholarMentorBonus(world, day, actorId, kind, target_id);
            return null;
          } catch {
            return { code: RuleError.ModifierTarget };
          }
        },
      },
      nightStages: [...SCHOLAR_MENTOR_NIGHT_STAGES, ...(base?.runtime.nightStages ?? [])],
      baselineAction: (role, request, pick, pickCamp, locale, world) => {
        if (request.allowedTools.includes("modify_skill") && world) {
          const state = scholarMentorStateForRole(role),
            targets = scholarMentorChoiceTargets(world, request.context.day, request.actorId);
          const mode =
            state?.remaining.enhance === 1
              ? "enhance"
              : state?.remaining.weaken === 1
                ? "weaken"
                : null;
          const target = targets.find((id) => id !== request.actorId) ?? targets[0] ?? null;
          return {
            name: "modify_skill",
            args: { mode: target === null ? null : mode, target_id: mode === null ? null : target },
          };
        }
        if (
          request.allowedTools.includes("bonus_action") &&
          world &&
          request.context.modifier_bonus_kind
        ) {
          const kind = request.context.modifier_bonus_kind,
            target =
              scholarMentorBonusTargets(world, request.context.day, request.actorId, kind)[0] ??
              null;
          return {
            name: "bonus_action",
            args: { kind, target_id: target, abstain: target === null },
          };
        }
        return base?.runtime.baselineAction?.(role, request, pick, pickCamp, locale, world) ?? null;
      },
    },
    presentation: nativeRolePresentation(roleNameId),
  };
}
export const SCHOLAR_ROLE_PROFILE = profile(Role.DayScholar);
export const MENTOR_ROLE_PROFILE = profile(Role.NightMentor);

/**
 * Owns Scholar/Mentor original abilities, target modifiers and resolved bonus grants. Inputs are
 * the paired modifier choices and native-target evidence; outputs are settled modifiers, legal
 * bonus actors and sourced conflict deaths. Close or abort removes that night's windows without
 * granting a new bonus to a replacement body.
 */
import type {
  ModifierState,
  ModifierMode,
  CommittedModifier,
  ModifierResolution,
  ModifierReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT, Camp, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { readModifierState, selectModifier, resolveModifiers } from "./state";
interface OriginalPlayer {
  abilityAuthority: () => boolean;
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface CasterAuthority {
  state: ModifierReadState;
  remaining: ModifierReadState["remaining"];
  history: ModifierReadState["history"];
  expected: string;
}
export type ModifierBonusKind = "check" | "guard" | "poison" | "kill";
interface Grant {
  actorId: number;
  kind: ModifierBonusKind;
  used: boolean;
  targetId: number | null;
}
interface ModifierNight {
  day: number;
  closed: boolean;
  aborted: boolean;
  living: ReadonlySet<number>;
  pending: Set<number>;
  selections: CommittedModifier[];
  resolution: ModifierResolution | null;
  grants: Map<number, Grant>;
  nativeTargets: Map<string, number | null>;
}
interface Board {
  players: ReadonlyMap<number, OriginalPlayer>;
  casters: ReadonlyMap<number, CasterAuthority>;
  night: ModifierNight | null;
}
const boards = new WeakMap<World, Board>();
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}

const missingAbilityField = Symbol("missing_ability_field");
function boundAbilityData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value))
    throw new Error("scholar_mentor_original_abilities_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) {
    if (key in value) throw new Error("scholar_mentor_original_abilities_invalid");
    return missingAbilityField;
  }
  if (!("value" in descriptor)) throw new Error("scholar_mentor_original_abilities_invalid");
  return descriptor.value;
}
function bindAbilities(role: RoleComponent): () => boolean {
  const container = boundAbilityData(role.privateState, "abilities");
  const prototype = Object.getPrototypeOf(role.privateState);
  if (container === missingAbilityField || container === undefined)
    return () =>
      Object.getPrototypeOf(role.privateState) === prototype &&
      boundAbilityData(role.privateState, "abilities") === container;
  if (
    !container ||
    typeof container !== "object" ||
    types.isProxy(container) ||
    Array.isArray(container)
  )
    throw new Error("scholar_mentor_original_abilities_invalid");
  const names = Reflect.ownKeys(container);
  const bindings = names.map((key) => {
    const ability = ownData(container, key);
    if (!ability || typeof ability !== "object" || types.isProxy(ability))
      throw new Error("scholar_mentor_original_abilities_invalid");
    const fields = [
      "id",
      "kind",
      "activation",
      "source",
      "state",
      "startsOnDay",
      "expiresAfterDay",
      "maxUses",
      "disabled",
      "deathExpired",
      "sourceDisclosed",
    ] as const;
    const values = fields.map((k) => boundAbilityData(ability, k)),
      source = ownData(ability, "source"),
      state = ownData(ability, "state");
    const sourceFields = ["kind", "role", "actorId", "abilityId"] as const,
      sourceValues = sourceFields.map((k) => boundAbilityData(source, k));
    const policyFields = [
        "targetPolicy",
        "actionPolicy",
        "selfHealRule",
        "knifeVisibility",
        "potionPolicy",
        "repeatPolicy",
      ] as const,
      policies = policyFields.map((k) => boundAbilityData(state, k));
    return () =>
      ownData(container, key) === ability &&
      fields.every((k, i) => boundAbilityData(ability, k) === values[i]) &&
      sourceFields.every((k, i) => boundAbilityData(source, k) === sourceValues[i]) &&
      policyFields.every((k, i) => boundAbilityData(state, k) === policies[i]);
  });
  return () =>
    Object.getPrototypeOf(role.privateState) === prototype &&
    boundAbilityData(role.privateState, "abilities") === container &&
    Reflect.ownKeys(container).length === names.length &&
    bindings.every((fn) => fn());
}

function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    !p.abilityAuthority() ||
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}

function stateIdentity(raw: unknown): string {
  const value = readModifierState(raw);
  if (!value) throw new Error("scholar_mentor_original_state_revoked");
  return JSON.stringify(value);
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("scholar_mentor_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("scholar_mentor_original_state_revoked");
  for (const [id, c] of b.casters) {
    if (
      ownData(b.players.get(id)!.privateState, "scholarMentor") !== c.state ||
      ownData(c.state, "remaining") !== c.remaining ||
      ownData(c.state, "history") !== c.history ||
      stateIdentity(c.state) !== c.expected
    )
      throw new Error("scholar_mentor_original_state_revoked");
  }
  return b;
}
export function installScholarMentorBoard(world: World): void {
  if (boards.has(world)) throw new Error("scholar_mentor_board_already_installed");
  const players = new Map<number, OriginalPlayer>(),
    seats = new Set<number>();
  const casters = new Map<number, CasterAuthority>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (
      !role ||
      !life ||
      types.isProxy(life) ||
      version === undefined ||
      (role.camp !== Camp.Wolf && role.camp !== Camp.Good)
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("scholar_mentor_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      abilityAuthority: bindAbilities(role),
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });

    if (String(role.role) === "day_scholar" || String(role.role) === "night_mentor") {
      const raw = ownData(role.privateState, "scholarMentor");
      const state = readModifierState(raw);
      if (!state || state.caster !== String(role.role) || state.history.length !== 0)
        throw new Error("scholar_mentor_original_roster_invalid");
      const original = raw as ModifierReadState;
      casters.set(id, {
        state: original,
        remaining: original.remaining,
        history: original.history,
        expected: stateIdentity(original),
      });
    }
  }
  resolveModifiers(
    [...players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: true,
    })),
    [],
  );
  if (casters.size !== 2) throw new Error("scholar_mentor_original_roster_invalid");
  boards.set(world, { players, casters, night: null });
}
export function isScholarMentorBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function assertScholarMentorRosterCurrent(world: World): void {
  if (boards.has(world)) requireBoard(world);
}
function night(world: World, day: number): { b: Board; n: ModifierNight } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.aborted)
    throw new Error("scholar_mentor_night_unavailable");
  return { b, n };
}
function resolved(
  world: World,
  day: number,
): { b: Board; n: ModifierNight; r: ModifierResolution } {
  const { b, n } = night(world, day);
  if (!n.resolution) throw new Error("scholar_mentor_night_unsettled");
  return { b, n, r: n.resolution };
}
export function beginScholarMentorNight(world: World, day: number): number[] {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day < 1 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || b.night.aborted || day !== b.night.day + 1))
  )
    throw new Error("scholar_mentor_night_invalid");
  const living = new Set([...b.players.values()].filter((p) => p.life.alive).map((p) => p.id));
  const pending = new Set(
    [...b.casters]
      .filter(
        ([id, c]) =>
          day >= 2 && living.has(id) && c.state.remaining.enhance + c.state.remaining.weaken > 0,
      )
      .map(([id]) => id),
  );
  b.night = {
    day,
    closed: false,
    aborted: false,
    living,
    pending,
    selections: [],
    resolution: null,
    grants: new Map(),
    nativeTargets: new Map(),
  };
  return [...pending];
}
export function scholarMentorChoicePending(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) && b.players.get(actorId)!.life.alive;
}
export function scholarMentorChoiceTargets(world: World, day: number, actorId: number): number[] {
  const { b, n } = night(world, day);
  return n.pending.has(actorId) ? [...n.living].filter((id) => b.players.get(id)!.life.alive) : [];
}
export function commitScholarMentorChoice(
  world: World,
  day: number,
  actorId: number,
  mode: ModifierMode | null,
  targetId: number | null,
): void {
  const { b, n } = night(world, day),
    c = b.casters.get(actorId);
  if (!c || !n.pending.has(actorId) || !b.players.get(actorId)!.life.alive || n.resolution)
    throw new Error("scholar_mentor_choice_scope_invalid");
  const next = selectModifier(
    c.state,
    day,
    mode,
    targetId,
    scholarMentorChoiceTargets(world, day, actorId),
  );
  (c.remaining as Pick<ModifierState["remaining"], "enhance">).enhance = next.remaining.enhance;
  (c.remaining as Pick<ModifierState["remaining"], "weaken">).weaken = next.remaining.weaken;
  Object.defineProperty(c.history, String(c.history.length), {
    value: next.history.at(-1)!,
    writable: true,
    enumerable: true,
    configurable: true,
  });
  c.expected = stateIdentity(c.state);
  n.pending.delete(actorId);
  if (mode !== null)
    n.selections.push({ actorId, caster: c.state.caster, mode, targetId: targetId! });
}
export function settleScholarMentorChoices(world: World, day: number): ModifierResolution {
  const { b, n } = night(world, day);
  if (n.pending.size || n.resolution) throw new Error("scholar_mentor_choices_unsettled");
  const r = resolveModifiers(
    [...b.players.values()].map((p) => ({
      id: p.id,
      role: String(p.roleName),
      camp: p.camp === Camp.Wolf ? "wolf" : "good",
      alive: n.living.has(p.id),
    })),
    n.selections,
  );
  n.resolution = r;
  for (const effect of r.goodEffects)
    if (effect.mode === "enhance")
      n.grants.set(effect.targetId, {
        actorId: effect.targetId,
        kind: effect.role === "seer" ? "check" : effect.role === "witch" ? "poison" : "guard",
        used: false,
        targetId: null,
      });
  if (r.bonusKnifeActorId !== null)
    n.grants.set(r.bonusKnifeActorId, {
      actorId: r.bonusKnifeActorId,
      kind: "kill",
      used: false,
      targetId: null,
    });
  return structuredClone(r);
}
export function scholarMentorBlocks(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): boolean {
  if (!boards.has(world)) return false;
  const { r } = resolved(world, day);
  if (kind === "kill") return r.blockWolfKnife;
  return r.goodEffects.some(
    (e) =>
      e.targetId === actorId &&
      e.mode === "weaken" &&
      ((e.role === "seer" && kind === "check") ||
        (e.role === "guard" && kind === "guard") ||
        (e.role === "witch" && kind === "poison")),
  );
}
export function scholarMentorKnifeEligible(world: World, day: number, actorId: number): boolean {
  const { b, n } = night(world, day),
    p = b.players.get(actorId);
  if (!p || !n.living.has(actorId) || !p.life.alive || p.camp !== Camp.Wolf) return false;
  if (String(p.roleName) === "wolf") return true;
  return (
    String(p.roleName) === "night_mentor" &&
    [...n.living].filter((id) => b.players.get(id)!.camp === Camp.Wolf).length === 1
  );
}
function nativeKey(actorId: number, kind: ModifierBonusKind): string {
  return kind === "kill" ? "pack:kill" : actorId + ":" + kind;
}
export function recordScholarMentorNativeTarget(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): void {
  const { b, n } = resolved(world, day),
    key = nativeKey(actorId, kind),
    p = b.players.get(actorId);
  if (
    !p ||
    !n.living.has(actorId) ||
    !p.life.alive ||
    n.nativeTargets.has(key) ||
    (targetId !== null && (!n.living.has(targetId) || !b.players.get(targetId)?.life.alive))
  )
    throw new Error("scholar_mentor_native_target_invalid");
  const expected =
    kind === "check" ? "seer" : kind === "guard" ? "guard" : kind === "poison" ? "witch" : null;
  if (expected ? String(p.roleName) !== expected : !scholarMentorKnifeEligible(world, day, actorId))
    throw new Error("scholar_mentor_native_actor_invalid");
  n.nativeTargets.set(key, targetId);
}
export function scholarMentorBonusActors(
  world: World,
  day: number,
  kind: ModifierBonusKind,
): number[] {
  const { n } = resolved(world, day);
  return [...n.grants.values()].filter((g) => g.kind === kind && !g.used).map((g) => g.actorId);
}
export function scholarMentorBonusTargets(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
): number[] {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
    g.used ||
    !b.players.get(actorId)!.life.alive ||
    !n.nativeTargets.has(key)
  )
    return [];
  const native = n.nativeTargets.get(key);
  return [...n.living].filter((id) => id !== native && b.players.get(id)!.life.alive);
}
export interface ModifierBonusReceipt {
  readonly target: NightLifeScope | null;
  readonly source: NightLifeScope;
  readonly isCurrent: () => boolean;
  readonly effectCurrent: () => boolean;
  readonly commit: () => void;
}
export function captureScholarMentorBonus(
  world: World,
  day: number,
  actorId: number,
  kind: ModifierBonusKind,
  targetId: number | null,
): ModifierBonusReceipt {
  const { b, n } = resolved(world, day),
    g = n.grants.get(actorId),
    p = b.players.get(actorId),
    key = nativeKey(actorId, kind);
  if (
    !g ||
    g.kind !== kind ||
    g.used ||
    !p?.life.alive ||
    !n.nativeTargets.has(key) ||
    (targetId !== null && !scholarMentorBonusTargets(world, day, actorId, kind).includes(targetId))
  )
    throw new Error("scholar_mentor_bonus_unavailable");
  const source: NightLifeScope = Object.freeze({
    id: actorId,
    life: p.life,
    version: aliveLifeVersion(p.life)!,
  });
  const t = targetId === null ? null : b.players.get(targetId)!;
  const target: NightLifeScope | null = t
    ? Object.freeze({ id: t.id, life: t.life, version: aliveLifeVersion(t.life)! })
    : null;
  let committed = false;
  const live = () => {
    try {
      return (
        requireBoard(world) === b &&
        b.night === n &&
        !n.closed &&
        !n.aborted &&
        n.grants.get(actorId) === g &&
        p.life.alive &&
        aliveLifeVersion(p.life) === source.version &&
        (!target || (target.life.alive && aliveLifeVersion(target.life) === target.version))
      );
    } catch {
      return false;
    }
  };
  const isCurrent = () => !committed && !g.used && live();
  return Object.freeze({
    source,
    target,
    isCurrent,
    effectCurrent: () => committed && g.used && g.targetId === targetId && live(),
    commit: () => {
      if (!isCurrent()) throw new Error("scholar_mentor_bonus_stale");
      g.used = true;
      g.targetId = targetId;
      committed = true;
    },
  });
}
export function scholarMentorConflictDeaths(world: World, day: number): NightLifeScope[] {
  const { b, r } = resolved(world, day);
  return r.pendingDeaths.map((id) => {
    const p = b.players.get(id)!;
    return Object.freeze({ id, life: p.life, version: aliveLifeVersion(p.life)! });
  });
}
export function closeScholarMentorNight(world: World, day: number): void {
  const { n } = resolved(world, day);
  if ([...n.grants.values()].some((g) => !g.used))
    throw new Error("scholar_mentor_bonus_unresolved");
  n.closed = true;
}
export function abortScholarMentorNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n && !n.closed) {
    n.aborted = true;
    n.closed = true;
  }
}

export function scholarMentorRoleCanKnife(world: World | undefined, role: RoleComponent): boolean {
  if (!world || !boards.has(world)) return false;
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.aborted) return false;
  const p = [...b.players.values()].find((p) => p.role === role);
  if (!p || !p.life.alive || !n.living.has(p.id)) return false;
  return (
    String(p.roleName) === "night_mentor" &&
    [...n.living].filter((id) => b.players.get(id)!.camp === Camp.Wolf).length === 1
  );
}
export function scholarMentorPackBlocked(world: World): boolean {
  if (!boards.has(world)) return false;
  const n = requireBoard(world).night;
  return !!n && !n.aborted && n.resolution?.blockWolfKnife === true;
}
export function scholarMentorStateForRole(
  role: RoleComponent | undefined,
): ModifierReadState | undefined {
  const name = ownData(role, "role"),
    camp = ownData(role, "camp");
  if (
    (name !== "day_scholar" && name !== "night_mentor") ||
    camp !== (name === "day_scholar" ? Camp.Good : Camp.Wolf)
  )
    return undefined;
  const raw = ownData(ownData(role, "privateState"), "scholarMentor"),
    value = readModifierState(raw);
  return value?.caster === name ? (raw as ModifierReadState) : undefined;
}

/**
 * 负责学者／导师本夜选择及独立加成阶段。
 * 输入为有资格的加成行动者、原目标 receipt 和已校验行动；输出保留已付效果及本职历史。
 * 加成毒在原 receipt.commit 与印记付款之后附带来源，独立于女巫或受赠瓶数。
 * 本族记录数组归 bonus-effect-records，原 receipt.commit 与 marks／效果追加顺序不变，重验仍在原检查点。
 * 本模块不重新计算别族的已付目标，也不将原体句柄或因果 Symbol 写入事件。
 */
import { COMPONENT, Camp, Phase, StatusMark, type RoleComponent } from "../../../../core";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { originalPoisonIntent, type NightLifeScope } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import {
  readScholarMentorBonusEffectRecords,
  scholarMentorBonusEffectRecordsForAppend,
} from "./bonus-effect-records";
import {
  beginScholarMentorNight,
  commitScholarMentorChoice,
  settleScholarMentorChoices,
  scholarMentorStateForRole,
  scholarMentorChoiceTargets,
  assertScholarMentorRosterCurrent,
  scholarMentorBonusActors,
  scholarMentorBonusTargets,
  captureScholarMentorBonus,
  scholarMentorConflictDeaths,
  type ModifierBonusKind,
} from "./night_frame";
const choose: NightStageHandler = {
  id: "scholar_mentor_choice",
  priority: 50,
  async execute(ctx) {
    const day = ctx.currentDay(),
      pending = beginScholarMentorNight(ctx.world, day);
    for (const actorId of ctx.world.entityIds()) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role),
        state = scholarMentorStateForRole(role);
      if (!state) continue;
      if (!pending.includes(actorId)) {
        const reason =
          day === 1
            ? "first_night"
            : ctx.world.getAliveEntityIds().includes(actorId)
              ? "exhausted"
              : "dead";
        ctx.events.push({
          timestamp: Date.now(),
          type: "modifier_choice_skipped",
          payload: { actorId, day, reason },
          audience: Object.freeze([actorId]),
        });
        continue;
      }
      const modes = (["enhance", "weaken"] as const).filter((mode) => state.remaining[mode] === 1);
      const request = ctx.makeRequest(actorId, ["modify_skill"], {
        stage: "scholar_mentor_choice",
        requiresAction: true,
        action_failure_policy: "error",
        allow_fallback: false,
        modifier_modes: modes,
        modifier_candidates: scholarMentorChoiceTargets(ctx.world, day, actorId),
      });
      assertScholarMentorRosterCurrent(ctx.world);
      const action = await ctx.actionProvider.getAction(request);
      assertScholarMentorRosterCurrent(ctx.world);
      if (!ctx.isCurrent() || ctx.currentDay() !== day)
        throw new Error("scholar_mentor_choice_stale");
      if (action?.name !== "modify_skill") throw new Error("scholar_mentor_choice_missing");
      const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
        phase: Phase.Night,
        day,
      });
      assertScholarMentorRosterCurrent(ctx.world);
      if (!ctx.isCurrent() || !result.ok || result.sanitizedCall?.name !== "modify_skill")
        throw new Error("scholar_mentor_choice_invalid");
      const { mode, target_id } = result.sanitizedCall.args;
      commitScholarMentorChoice(ctx.world, day, actorId, mode, target_id);
      ctx.events.push({
        timestamp: Date.now(),
        type: "modifier_choice_committed",
        payload: { actorId, day, mode, targetId: target_id },
        audience: Object.freeze([actorId]),
      });
    }
    const result = settleScholarMentorChoices(ctx.world, day);
    ctx.state.modifierDeaths = scholarMentorConflictDeaths(ctx.world, day);
    if (result.conflict !== null)
      ctx.events.push({
        timestamp: Date.now(),
        type: "modifier_conflict_resolved",
        payload: { day, kind: result.conflict, targetId: result.pendingDeaths[0]! },
        audience: Object.freeze([]),
      });
  },
};
export function assertScholarMentorBonusEffects(ctx: NightStageContext): void {
  assertScholarMentorRosterCurrent(ctx.world);
  for (const effect of readScholarMentorBonusEffectRecords(ctx.state)) {
    const target = effect.receipt.target;
    if (
      !effect.receipt.effectCurrent() ||
      (target &&
        (ctx.world.getComponent(target.id, COMPONENT.Alive) !== target.life ||
          aliveLifeVersion(target.life) !== target.version)) ||
      (effect.marks &&
        target &&
        ctx.world.getComponent(target.id, COMPONENT.StatusMarks) !== effect.marks)
    )
      throw new Error("scholar_mentor_bonus_effect_stale");
  }
}
function bonus(kind: ModifierBonusKind, priority: number): NightStageHandler {
  return {
    id: "scholar_mentor_bonus_" + kind,
    priority,
    async execute(ctx) {
      const day = ctx.currentDay();
      for (const actorId of scholarMentorBonusActors(ctx.world, day, kind)) {
        const request = ctx.makeRequest(actorId, ["bonus_action"], {
          stage: "scholar_mentor_bonus",
          requiresAction: true,
          action_failure_policy: "error",
          allow_fallback: false,
          modifier_bonus_kind: kind,
          modifier_bonus_candidates: scholarMentorBonusTargets(ctx.world, day, actorId, kind),
        });
        assertScholarMentorRosterCurrent(ctx.world);
        const action = await ctx.actionProvider.getAction(request);
        assertScholarMentorRosterCurrent(ctx.world);
        if (!ctx.isCurrent() || ctx.currentDay() !== day)
          throw new Error("scholar_mentor_bonus_stale");
        if (action?.name !== "bonus_action" || action.args.kind !== kind)
          throw new Error("scholar_mentor_bonus_missing");
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        assertScholarMentorRosterCurrent(ctx.world);
        if (
          !ctx.isCurrent() ||
          !result.ok ||
          result.sanitizedCall?.name !== "bonus_action" ||
          result.sanitizedCall.args.kind !== kind
        )
          throw new Error("scholar_mentor_bonus_invalid");
        const { target_id: targetId, abstain } = result.sanitizedCall.args;
        const receipt = captureScholarMentorBonus(ctx.world, day, actorId, kind, targetId);
        const inspection =
          kind === "check" && targetId !== null
            ? resolveInspection(ctx.world, targetId, "camp", ctx.roleCatalog)
            : null;
        if (kind === "check" && targetId !== null && !inspection)
          throw new Error("scholar_mentor_inspection_invalid");
        if (!receipt.isCurrent() || !ctx.isCurrent()) throw new Error("scholar_mentor_bonus_stale");
        receipt.commit();
        if (targetId !== null && receipt.target) {
          if (kind === "check") {
            ctx.state.seerChecks.push({
              seerId: actorId,
              targetId,
              isWerewolf: inspection!.camp === Camp.Wolf,
              result: { ...inspection! },
            });
            scholarMentorBonusEffectRecordsForAppend(ctx.state).push({ kind, receipt });
          } else {
            const marks = ctx.ensureMarks(targetId);
            if (kind === "guard") {
              marks.add(StatusMark.GuardMark);
              (ctx.state.guardClaims ??= []).push({
                target: receipt.target,
                marks,
                isCurrent: receipt.effectCurrent,
              });
            } else if (kind === "poison") {
              marks.add(StatusMark.PoisonMark);
              // source 在原对象字段求值位置读取一次；receipt 的付款和当前性仍归 frame。
              let effectSource: NightLifeScope;
              (ctx.state.poisonClaims ??= []).push(originalPoisonIntent({
                source: (effectSource = receipt.source),
                target: receipt.target,
                isCurrent: receipt.effectCurrent,
              }, {
                family: "scholar-mentor",
                day,
                stage: "scholar_mentor_bonus",
                actorLife: effectSource,
                requestedTargetId: targetId,
                abilityId: "bonus:poison",
              }));
            } else {
              marks.add(StatusMark.WolfKillMark);
              (ctx.state.modifierKnifeTargets ??= []).push(targetId);
            }
            scholarMentorBonusEffectRecordsForAppend(ctx.state).push({ kind, receipt, marks });
          }
        }
        ctx.events.push({
          timestamp: Date.now(),
          type: "modifier_bonus_resolved",
          payload: {
            actorId,
            day,
            kind,
            targetId,
            abstain,
            ...(inspection ? { isWerewolf: inspection.camp === Camp.Wolf } : {}),
          },
          audience: Object.freeze([actorId]),
        });
      }
      assertScholarMentorBonusEffects(ctx);
    },
  };
}
export const SCHOLAR_MENTOR_NIGHT_STAGES: NightStageHandler[] = [
  choose,
  bonus("guard", 350),
  bonus("kill", 450),
  bonus("poison", 550),
  bonus("check", 650),
];

/**
 * Exposes Scholar/Mentor's eligibility query and concrete cleanup-transfer ports.
 * Query inputs are actor ID, night day and guard/check kind; output retains the
 * original settled modifier predicate, readable-board/roster assertions and
 * errors. Binding captures no state
 * snapshot and grants no World access, poison/knife commit or resource writer.
 * Lifecycle inputs are original World/day reads; its unit only transfers cleanup
 * at the original late point. Manager close and repeated abort keep their timing,
 * while frame authority owns grant completion, aborted fate and roster failures.
 * Named native-target recording keeps its original paid fact write; the eligibility query remains a distinct readonly interface with no commit method.
